-- v0.14.0.204B Additional original, fictional educational cases.
INSERT INTO public.gu_founder_educational_releases_v014190
(slug,title,category,audience,body,competency_code,review_state,rights_cleared,available_from,reviewed_by)
SELECT lessons.slug,lessons.title,lessons.category,lessons.audience,lessons.body,
lessons.competency_code,'approved',true,now(),r.user_id
FROM (VALUES ('founder-vwap-weighted-average-01','VWAP and Volume Weighted Prices','early_teaching','shared','VWAP is the volume-weighted average price. For a simplified three-trade lesson, calculate sum of price times number of shares, then divide by total shares. Fictional trades: 100 shares at $3.00, 300 at $3.10, 600 at $3.20. Weighted dollar total = $300 + $930 + $1,920 = $3,150 for 1,000 shares; simplified VWAP = $3.15. An unweighted average of the three trade prices would be $3.10. Why different? More shares traded at the higher price. Actual chart VWAP can vary with session boundary and price input. VWAP above or below price never establishes a guaranteed trade. Examine momentum, support, volume, spread and the higher timeframe. Independent problem: 200 shares at $4.00 and 800 at $4.25. Find VWAP and explain which price influences it more.','VWAP_CONTEXT'),
('founder-failed-breakout-01','False Breakout and Hindsight Control','early_teaching','shared','A breakout moves beyond previously observable resistance. A failed breakout is identified only when additional price observations establish failure to hold. Fictional resistance: $6.00. A one-minute candle reaches $6.12 but closes $5.98. The wick shows a trade above resistance but a close below it. The following completed candle closes $5.89 with increased volume. At $6.12, nobody could know how that first candle would close. The second close strengthens the failed-breakout interpretation but does not prove the next candle. Consider VWAP, bid-ask spread, volume, multi-timeframe highs and predefined invalidation. Independent practice: label exactly when resistance was exceeded, when the first close fell back below it, and what later evidence justified calling it failed. Reject explanations relying on future bars.','FAILED_BREAKOUT'),
('founder-extended-candle-liquidity-01','Extended Challenge: Candle Pressure and Spread','challenge','council','All figures are invented solely for education. At the completed candle, Open is $2.75, High $2.98, Low $2.72 and Close $2.94 on 900,000 shares. Previous 20-bar average volume is 200,000. Bid is $2.93; ask is $2.97. Pause and calculate real-body percentage of range, relative volume and spread percentage of ask. Work first: real body $0.19, full range $0.26 and body-to-range 73.08%; relative volume 4.5x; spread $0.04 / $2.97 = about 1.35%. That spread is significant for a quick scalp, especially if the next fill differs from the quote. A large bullish body and heavy volume alone cannot justify a buy: resistance, VWAP, higher timeframes, liquidity and stop location are missing. Independent follow-up: invent a narrower bid-ask spread, recalculate its percentage and explain which missing decision inputs remain.','CANDLE_READING'),
('founder-extended-risk-per-share-01','Extended Challenge: Risk and Slippage','challenge','council','Fictional paper trade only. Entry $3.60; planned stop $3.48; risk budget $18. Risk per share = $3.60 minus $3.48 = $0.12. The floor of $18 divided by $0.12 is 150 shares, requiring $540 notional buying power. A stop trigger is not a guaranteed execution price. If the actual sell executes at $3.44, realized price risk is $0.16 per share, and 150 shares lose $24 instead of the planned $18. Extra slippage must be modeled, especially near halts, illiquid quotes and widened spreads. Independent exercise: entry $5.25, stop $5.08, risk budget $21. Calculate share count using floor division, capital needed, and the dollar risk if exit slips by another $0.05. This exercise does not recommend trading.','RISK_PER_SHARE')) AS lessons(slug,title,category,audience,body,competency_code)
CROSS JOIN (SELECT user_id FROM public.admin_user_roles WHERE role_code='OWNER'
AND (expires_at IS NULL OR expires_at>now()) ORDER BY granted_at LIMIT 1) r
ON CONFLICT(slug) DO NOTHING;